// ⚙️ RÉGLAGES : le seul endroit à modifier.
// maitre : le document Arrivées-Départs (annuaire du personnel présent).
// cibles : les Grist « esclaves » à tenir à jour (table Gouv_Utilisateurs de la norme). Ajouter une ligne par document.
// essai : true = calcule et affiche les changements (nœud « Calculer les changements ») SANS rien écrire.
//         Passer à false après avoir vérifié un premier lancement à la main.
// desactivationsMax : au-delà, on ne désactive personne (une lecture ratée du maître ne vide pas l'annuaire).
return [{ json: {
  grist: 'https://grist.numerique.gouv.fr',
  maitre: { nom: 'Arrivées-Départs MOM', docId: '7vFZ964YgDgJ', table: 'Personnel_summary_Courriel' },
  cibles: [
    { nom: 'Gouvernance', docId: 'jQ3omn87Zkei' },
    // { nom: 'Autre application', docId: 'xxxxxxxxxxxx' },
  ],
  essai: true,
  desactivationsMax: 10,
} }];

// Agents présents lus dans l'annuaire du maître, mis au format des Grist esclaves.
// Nom affiché : « Prénom NOM » ; entité : le bureau (ex. BSSIOM), sinon la direction (ex. DGOM).
// Un courriel n'apparaît qu'une fois (le premier trouvé), même s'il est écrit avec des majuscules différentes.
const parCourriel = new Map();
for (const r of $input.first().json.records || []) {
  const f = r.fields;
  if (f.Present === false || !f.Courriel) continue;
  const courriel = String(f.Courriel).trim().toLowerCase();
  if (parCourriel.has(courriel)) continue;
  parCourriel.set(courriel, {
    courriel,
    nom: [f.Prenom, f.Nom].filter(Boolean).join(' ').trim(),
    bureau: f.Bureau || '',
    direction: f.Entite || '',
    fonction: f.Fonction || '',
  });
}
const agents = [...parCourriel.values()];
if (!agents.length) throw new Error("Annuaire vide : la synchronisation s'arrête (sécurité : on ne désactive personne sur une lecture ratée).");
return [{ json: { agents } }];

// Une ligne par Grist esclave, avec la liste des agents du maître et les réglages utiles plus loin.
const r = $('Réglages').first().json;
const agents = $('Préparer les agents').first().json.agents;
return r.cibles.map((c) => ({ json: { ...c, grist: r.grist, essai: r.essai, desactivationsMax: r.desactivationsMax, agents } }));

// Ce qu'il faut changer dans un Grist esclave (Gouv_Utilisateurs), en comparant au maître par courriel.
// Règles :
//  - agent du maître absent de l'esclave : ajouté (Nom, Courriel, Entité, Fonction, Actif) ; SANS rôle :
//    il ne voit que l'accueil tant qu'un administrateur de l'application ne lui en a pas donné un ;
//  - agent déjà présent : Nom, Entité et Fonction mis à jour depuis le maître ; le Rôle n'est JAMAIS touché ;
//  - personne de l'esclave absente du maître (agent parti) : désactivée, SEULEMENT si c'est la synchro qui l'a
//    créée (Créé par = un compte de service) ; les personnes ajoutées à la main ne sont jamais désactivées.
const cible = $('Cibles').item.json;
const entites = ($('Lire les entités').item.json.records || []);
const colonnes = ($('Lire les colonnes').item.json.columns || []).map((c) => c.id);
const users = $json.records || [];
const norm = (s) => String(s || '').trim().toLowerCase();
const compteDeService = (c) => /@serviceaccounts\.invalid$/.test(norm(c));
const idEntite = (nom) => (nom ? (entites.find((e) => norm(e.fields.Nom) === norm(nom)) || {}).id : undefined);
const aFonction = colonnes.includes('Fonction');

const parCourriel = new Map(users.map((u) => [norm(u.fields.Courriel), u]));
const ajouts = [], majs = [];
for (const a of cible.agents) {
  const entite = idEntite(a.bureau) || idEntite(a.direction);   // introuvable : on ne touche pas à l'entité
  const champs = { Nom: a.nom, ...(entite ? { Entite: entite } : {}), ...(aFonction ? { Fonction: a.fonction } : {}) };
  const u = parCourriel.get(a.courriel);
  if (!u) { ajouts.push({ fields: { Courriel: a.courriel, Actif: true, ...champs } }); continue; }
  const diff = Object.fromEntries(Object.entries(champs).filter(([k, v]) => (u.fields[k] ?? '') !== v));
  // une fiche créée par la synchro et désactivée revient quand l'agent est de nouveau présent
  if (u.fields.Actif === false && compteDeService(u.fields.CreePar)) diff.Actif = true;
  if (Object.keys(diff).length) majs.push({ id: u.id, fields: diff });
}
const presents = new Set(cible.agents.map((a) => a.courriel));
const departs = users.filter((u) => {
  const c = norm(u.fields.Courriel);
  return u.fields.Actif !== false && c && !presents.has(c) && !compteDeService(c) && compteDeService(u.fields.CreePar);
});
// garde-fou : trop de départs d'un coup = sans doute une lecture incomplète du maître ; on ne désactive personne
const departsBloques = departs.length > cible.desactivationsMax;
if (!departsBloques) for (const u of departs) majs.push({ id: u.id, fields: { Actif: false } });
return { json: { nom: cible.nom, docId: cible.docId, grist: cible.grist, essai: cible.essai, ajouts, majs,
  resume: `${cible.essai ? '[ESSAI, rien écrit] ' : ''}${cible.nom} : ${ajouts.length} ajout(s), ${majs.length} mise(s) à jour`
    + (departsBloques ? ` ; ${departs.length} départs NON appliqués (plus de ${cible.desactivationsMax} : vérifier l'annuaire)` : '') } };
